(()=>{
 const Core=CompanionCore,chapters=companionChapters,KEY='benjamin-companion-vn-v2',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let saved=null,storageOK=true;try{saved=JSON.parse(localStorage.getItem(KEY))}catch{storageOK=false}let state=Core.normalize(saved,chapters),preview=state.selected,typing=false,typeTimer=null,fullLine='',lastFocus=null,mapScroll=null,lastView='map';
 const app=document.getElementById('novel'),dialog=document.getElementById('novel-dialog');
 function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false}}
 function image(c){return 'assets/unique/'+c.image+'.jpg'}
 function status(i){return state.completed.includes(chapters[i].id)?'complete':i<=Core.unlocked(state,chapters)?'current':'locked'}
 function topbar(){return `<header class="vn-header"><a href="index.html" class="website-return">导览网站 ↗</a><button class="vn-brand" data-action="map">与本雅明同行 <span lang="fr">《拱廊街计划》 · Le Livre des passages</span></button><nav aria-label="游戏菜单"><button data-action="map" aria-current="${state.view==='map'?'page':'false'}">关卡地图</button><button data-action="album" aria-current="${state.view==='album'?'page':'false'}">语录手札 <small>${state.quotes.length}</small></button><button data-action="settings">设置与存档</button></nav></header>`}
 function mapPage(){let c=chapters[preview],s=status(preview),started=state.steps[c.id];let path=chapters.map((c,i)=>(i?'L':'M')+' '+c.map[0]*12+' '+c.map[1]*8.2).join(' ');return `<section class="chapter-select"><div class="map-heading"><div><p lang="fr">La carte de notre promenade</p><h1>巴黎，谁有权留下自己的声音？</h1></div><p>寻找被删去的证言 · 与本雅明并肩辩论<br><small>${state.completed.length} / ${chapters.length} 章已走过 · ${Core.memories(state,chapters).length} 段同行回忆</small></p></div><div class="map-layout"><aside class="chapter-preview"><div class="preview-painting"><img src="${image(c)}" alt="${c.place}的油画场景"></div><div class="preview-copy"><div class="chapter-kicker"><span>${preview===0?'PROLOGUE':preview===11?'ÉPILOGUE':'CHAPITRE '+String(preview).padStart(2,'0')}</span><b>${s==='complete'?'已走过':s==='locked'?'尚未解锁':'正在同行'}</b></div><p lang="fr">${c.fr}</p><h2>${c.title}</h2><p class="preview-place">${c.place}</p><dl><dt>你会遇见</dt><dd>${c.encounter}</dd><dt>这一站的故事</dt><dd>${c.event}</dd></dl><button class="vn-primary" data-action="enter" data-index="${preview}" ${s==='locked'?'disabled':''}>${s==='locked'?'先走完前一站':s==='complete'?'重温这一章 ↗':started?'继续这段对话 ↗':'从这里开始同行 ↗'}</button><p class="preview-hint">${s==='locked'?'沿着点亮的路线逐站前进。':'你的决定会得到当事人的回应，并留下不同的调查札记。'}</p></div></aside><div class="chapter-map-viewport" tabindex="0" aria-label="巴黎关卡地图，可滚动查看"><div class="chapter-map"><img src="assets/unique/painted-paris-map.jpg" alt="巴黎油画场景地图，艺术演绎"><div class="map-shade"></div><svg viewBox="0 0 1200 820" aria-hidden="true" preserveAspectRatio="none"><path class="route-shadow" d="${path}"/><path class="route-dashes" d="${path}"/></svg><span class="map-inscription" lang="fr">Paris des passages</span>${chapters.map((ch,i)=>`<button class="chapter-node ${status(i)} ${i===preview?'selected':''}" data-action="select" data-index="${i}" style="left:${ch.map[0]}%;top:${ch.map[1]}%" aria-label="${i===0?'序章':i===11?'终章':'第'+i+'章'}，${ch.title}，${status(i)==='locked'?'未解锁':status(i)==='complete'?'已走过':'可进入'}"><i>${status(i)==='complete'?'✓':i===0?'序':i===11?'终':String(i).padStart(2,'0')}</i><span>${ch.title}</span></button>`).join('')}<div class="map-legend"><span>● 正在同行</span><span>✓ 已走过</span><span>○ 尚未解锁</span></div><small class="map-scenic-note">同行场景路线 · 非实地导航</small></div></div></div><p class="scroll-map-note">小屏可左右移动关卡地图；点选圆点，再从左侧卡片进入剧情。</p></section>`}
 const moodNames={thoughtful:'凝神思索',concerned:'眉头紧锁',firm:'据理力争',resolute:'坚定不移',animated:'豁然开朗',weary:'沉默片刻',relieved:'神色舒展'};
 const playerGestures={警觉:'你眉头微蹙，把校样移到光下。',果断:'你停住笔，抬头把话说完。',怀疑:'你没有点头，手指仍停在那条证据上。',专注:'你侧过身听，笔尖悬在空白处。',审慎:'你划去一个过于肯定的词，重新开口。',踌躇:'你几次想落笔，最后先把问题说了出来。',惊异:'你睁大眼睛，重新看向刚才忽略的地方。',认真:'你把纸铺平，请对方再说一次。',好奇:'你稍稍前倾，等着下一句。',克制:'你攥住纸角，放慢了语速。',郑重:'你合上自己的笔记，先听对方把话说完。',愧疚:'你低头看见自己先前写下的结论，缓缓划掉。',紧迫:'你看了一眼钟，又把手表收进口袋。',愤懑:'你眉头紧锁，把已经写好的赞辞翻到背面。',紧绷:'你不自觉地握紧笔，重新确认四周。',坚定:'你直起身，把材料放回桌子中央。',惭愧:'你垂下目光，在自己的误判旁留下更正。',投入:'你抽出一张空纸，把两种说法并列写下。',昂扬:'你抬起头，回应的声音比方才清楚。',耐心:'你把钟表推远，示意对方继续。',焦灼:'你来回摸索纸边，终于停下来深吸一口气。',释然:'你松开攥紧的纸页，肩膀慢慢放松。',期待:'你在页边留下一个问号，笑着抬头。',不服气:'你挑起眉毛，在他的结论旁再添一条反证。'};
 function currentText(){let c=chapters[state.selected],step=Core.node(state,chapters),line=Core.line(state,chapters);if(step==='choice')return {...line,speaker:state.name||'你',character:'player',text:c.question,kind:'选择你的回应',playerEmotion:'斟酌措辞'};if(line.character==='player'||line.speaker==='你')line.speaker=state.name||'你';return line}
 function briefingPage(){const c=chapters[state.selected],b=c.briefing,resumed=Core.node(state,chapters)!=='arrival';return `<section class="station-briefing" aria-labelledby="briefing-heading"><div class="briefing-art"><img src="${image(c)}" alt="${esc(c.place)}的场景"><div class="briefing-location"><p lang="fr">LE LIVRE DES PASSAGES · ${String(state.selected+1).padStart(2,'0')} / 12</p><span>${esc(c.time)}</span><h1 id="briefing-heading">${esc(c.title)}</h1><p>${esc(c.place)}</p><span lang="fr">${esc(c.fr)}</span></div><div class="briefing-mission"><span>这一站的任务</span><p>${esc(b.objective)}</p></div></div><article class="briefing-article" tabindex="-1"><div class="briefing-paper-top"><span>走进这一站</span><button data-action="map">← 关卡地图</button></div><section class="briefing-situation"><h2>为何来到这里</h2><p>${esc(b.lead[0])}</p></section><section class="briefing-previous"><h2>你要做什么</h2><p>${esc(b.objective)}</p></section><section class="briefing-stakes"><h2>办完以后，去哪里</h2><p>${esc(b.next)}</p></section><details class="briefing-extra"><summary>看看在场人物与线索</summary><dl>${b.people.map(x=>`<dt>${esc(x.name)}</dt><dd>${esc(x.role)}</dd>`).join('')}</dl><ul>${b.clues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><div class="briefing-actions"><button class="vn-primary" data-action="begin-scene">${resumed?'回到对话':'去问个明白'} ↗</button><p>原创文学剧情 · 你与本雅明是朋友</p></div></article></section>`}
 function actorMarkup(line){const actor=Core.actor(line);if(!actor)return '';return `<div class="actor-sprite actor-${actor.side}" data-character="${actor.id}" data-speaking="true"><img src="${actor.file}" alt="${esc(line.speaker)}的独立角色立绘"></div>`}
 const warmedCharacters=new Set();
 function warmCharacters(c){if(typeof Image!=='function')return;const files=new Set(['assets/game/cast/player.png',...['thoughtful','concerned','resolute'].map(m=>'assets/game/benjamin-'+m+'.png'),...[...(c.events||[]),...(c.optionEvents||[]).flat()].map(e=>Core.actor(e)?.file).filter(Boolean)]);for(const file of files){if(warmedCharacters.has(file))continue;warmedCharacters.add(file);const img=new Image();img.decoding='async';img.src=file}}
 function scenePage(){let c=chapters[state.selected],step=Core.node(state,chapters),line=currentText(),choice=step==='choice',quote=step==='aphorism',actor=Core.actor(line);if(step==='end')return chapterEnd();let steps=Core.timeline(c,state.choices[c.id]).filter(x=>x!=='end'),mood=line.emotion||'thoughtful',reflection=step.startsWith('reflection-')||step==='afterthought';return `<section class="vn-stage mood-${mood} ${actor?'has-speaker':'narration-stage'}" data-speaker-side="${actor?.side||'none'}" data-light="${[0,1,4,7,10,11].includes(state.selected)?'day':'evening'}" aria-label="${c.title}剧情"><div class="scene-background"><img src="${image(c)}" alt="${c.place}油画场景，艺术演绎"></div><div class="scene-vignette"></div><div class="scene-topline"><div><span>${c.time} · ${String(state.selected+1).padStart(2,'0')} / 12</span><h1>${c.title}</h1><p>${c.place}</p></div><div class="scene-navigation"><button data-action="context">本站背景</button><button data-action="map" class="scene-map-return">← 关卡地图</button></div></div><p class="scene-french" lang="fr">${c.fr}</p>${actorMarkup(line)}${actor?`<div class="speaker-state"><b>${esc(line.speaker)}</b><span>${actor.id==='player'?esc(line.playerEmotion):moodNames[mood]||'正在交谈'}</span></div>`:''}<div class="scene-objective"><span>当前要问清</span><p>${esc(c.briefing?.objective||c.event)}</p></div><div tabindex="-1" role="group" aria-label="${esc(line.speaker+'：'+line.text)}" class="vn-dialogue ${quote?'aphorism-dialogue':''} ${reflection?'reflection-dialogue':''}"><div class="speaker-name">${esc(line.speaker)}<small>${quote?'根据刚才的事件归纳 · 观点改写':choice?'你准备怎样回应':reflection?'把眼前的事想清楚':'原创剧情'}</small></div><div class="dialogue-inner"><p class="spoken-line ${quote?'quote-line':''}" id="spoken-line" aria-hidden="true">${esc(line.text)}</p><p class="sr-only">${esc(line.speaker)}：${esc(line.text)}</p>${(step==='player-line'||step==='afterthought')&&playerGestures[line.playerEmotion]?`<p class="player-reaction"><span>你的神态</span>${esc(playerGestures[line.playerEmotion])}</p>`:''}${choice?`<div class="dialogue-choices" role="group" aria-label="你的回应">${c.options.map((o,i)=>`<button data-action="choose" data-option="${i}"><span>0${i+1}</span>${esc(o[0])}<b>↗</b></button>`).join('')}</div>`:`<div class="dialogue-controls"><span>${steps.indexOf(step)+1} / ${steps.length} · 空格继续</span><div><button data-action="log" class="dialogue-log">回看对话</button><button data-action="next" class="continue-button">${step==='farewell'?'结束这一章':'继续'} <b>▸</b></button></div></div>`}</div></div><p class="stage-note">${quote?'依据卷轴 '+esc(c.reference)+' 改写，不是原著逐字引文；相关解释已在前文对话中展开。':'原创跨时空剧情 · 你与本雅明作为朋友互相启发，遇到的人物为虚构角色'}</p></section>`}
 function chapterEnd(){let c=chapters[state.selected],last=state.selected===chapters.length-1;return `<section class="chapter-end"><div class="end-background"><img src="${image(c)}" alt="${c.place}"></div><div class="chapter-end-card" tabindex="-1"><p lang="fr">Les notes de notre enquête</p><span class="chapter-finished">${last?'旅程终章已完成':'这一章，已走过'}</span><h1>${c.title}</h1><p class="memory-line">${c.options[state.choices[c.id]||0][2]}</p><blockquote>${c.aphorism}</blockquote><p class="thought-explanation">${esc(c.reflection?.[1]?.text||'')}</p><small>依据本雅明观点改写 · 卷轴 ${c.reference}</small><p class="next-stop">${esc(c.briefing.next)}</p><div class="end-actions">${last?'<button class="vn-primary" data-action="ending">查看调查后记 ↗</button>':`<button class="vn-primary" data-action="next-map">下一站已解锁 · 返回地图 ↗</button>`}<button data-action="album">查看语录手札</button></div></div></section>`}
 function albumPage(){let memories=Core.memories(state,chapters);return `<section class="album-page"><div class="album-heading"><p lang="fr">Le carnet des pensées</p><h1>把同行的话，留在这里。</h1><p>语录式台词依据观点改写，旁注卷轴供自愿查阅；阅读资料不是过关条件。</p></div><div class="thought-grid">${chapters.filter(c=>state.quotes.includes(c.id)).map(c=>`<article class="thought-card"><div><span>${c.time}</span><em lang="fr">${c.fr}</em></div><p class="thought-context">${esc(c.event)}</p><blockquote>${c.aphorism}</blockquote><p class="thought-explanation">${esc(c.reflection?.[1]?.text||'')}</p><p>${c.place}</p><small>依据本雅明观点改写 · 卷轴 ${c.reference}</small><div class="thought-links"><button data-action="replay" data-index="${chapters.indexOf(c)}">重温相遇 ↗</button><a href="index.html#read/${c.reference.split('、')[0]}" target="_blank" rel="noopener">可选：查阅卷轴 ↗</a></div></article>`).join('')||'<div class="empty-album"><h2>还没有收下第一句话。</h2><p>从图书馆出发，与他完成一段对话。</p><button class="vn-primary" data-action="map">回到关卡地图 ↗</button></div>'}</div>${memories.length?`<section class="memories"><h2>你们的同行回忆</h2>${memories.map(m=>`<p><span>${m.title}</span>${m.text}</p>`).join('')}</section><button class="vn-primary" data-action="export">导出语录与同行回忆</button>`:''}</section>`}
 function endingPage(){let memories=Core.memories(state,chapters);return `<section class="ending-page"><img class="ending-image" src="assets/unique/place-richelieu.jpg" alt="灯下的图书馆"><article><p lang="fr">La discussion reste ouverte</p><h1>争论还在继续，朋友。</h1><p>调查后记 · ${esc(state.name||'同行者')}与瓦尔特·本雅明</p><p>画刊并没有因一夜的争论而改变整座城市。但在这份准备交付的稿件里，广告背后的人、无权署名的人和不同意我们的人，都保留了自己的声音。</p><p>${memories.filter((_,i)=>[1,5,7,11].includes(i)).map(m=>esc(m.text)).join('')}</p><p>“我们未必得出相同的结论，但可以核对同一份证据。下次见面，再把今天未说完的问题摆到桌上。”本雅明合上手稿，你们约好继续讨论。</p><p class="letter-signature">一场调查结束，一段对话继续。<br><small>原创游戏结语，非历史书信或真实出版事件</small></p><div class="end-actions"><button class="vn-primary" data-action="album">打开调查手札 ↗</button><button data-action="map">回看完整路线</button><a href="index.html">回到《拱廊街计划》导览 ↗</a></div></article></section>`}
 function stopTyping(){if(typeTimer){clearInterval(typeTimer);typeTimer=null}typing=false}
 function startTyping(){let p=document.getElementById('spoken-line');if(!p)return;let line=currentText();fullLine=line.text;if(state.mutedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches||Core.node(state,chapters)==='choice')return;p.textContent='';let n=0,chars=Array.from(fullLine);typing=true;typeTimer=setInterval(()=>{n+=2;p.textContent=chars.slice(0,n).join('');if(n>=chars.length)stopTyping()},23)}
 function render(){const priorMap=document.querySelector?.('.chapter-map-viewport');if(priorMap)mapScroll={left:priorMap.scrollLeft,top:priorMap.scrollTop};stopTyping();document.body.classList.toggle('vn-reduced',state.mutedMotion);let content=state.view==='briefing'?briefingPage():state.view==='scene'?scenePage():state.view==='album'?albumPage():state.view==='ending'?endingPage():mapPage();app.innerHTML=topbar()+content+(!storageOK?'<p class="vn-storage-note" role="status">当前浏览器无法保存进度，请保留页面并及时导出回忆。</p>':'');save();if(state.view==='scene'&&Core.node(state,chapters)!=='end')startTyping();if(state.view==='scene')document.querySelector?.('.vn-dialogue,.chapter-end-card')?.focus({preventScroll:true});if(state.view==='briefing'){warmCharacters(chapters[state.selected]);document.querySelector?.('.briefing-article')?.focus({preventScroll:true});window.scrollTo?.(0,0)}if(state.view==='scene'&&lastView!=='scene')window.scrollTo?.(0,0);lastView=state.view;const newMap=document.querySelector?.('.chapter-map-viewport');if(newMap){if(mapScroll){newMap.scrollLeft=mapScroll.left;newMap.scrollTop=mapScroll.top}else{const canvas=document.querySelector('.chapter-map');newMap.scrollLeft=Math.max(0,canvas.clientWidth*chapters[preview].map[0]/100-newMap.clientWidth/2);newMap.scrollTop=Math.max(0,canvas.clientHeight*chapters[preview].map[1]/100-newMap.clientHeight/2)}}}
 function advance(){if(state.view!=='scene')return;if(typing){stopTyping();let p=document.getElementById('spoken-line');if(p)p.textContent=fullLine;return}if(Core.next(state,chapters)){save();render()}}
 function showDialog(html){lastFocus=document.activeElement;document.getElementById('dialog-content').innerHTML=html;dialog.showModal()}
 function closeDialog(){dialog.close();lastFocus?.focus?.()}
 function settings(){showDialog(`<h2>留给这场同行的名字</h2><p>你是一位32岁的男性研究伙伴，也是本雅明的朋友。称呼可以留空。</p><label>你的称呼<input id="player-name" maxlength="24" value="${esc(state.name)}" placeholder="同行者"></label><label class="motion-setting"><input type="checkbox" id="reduce-animation" ${state.mutedMotion?'checked':''}>减少文字与场景动效</label><button class="vn-primary" data-dialog-action="save-settings">保存并返回</button><div class="save-explanation"><p>每段对话和选择都会自动保存。关闭再打开游戏，可从地图继续上次的相遇。</p><button data-dialog-action="export">导出回忆</button><button data-dialog-action="confirm-reset">重新开始</button></div>`) }
 function log(){let c=chapters[state.selected],order=Core.timeline(c,state.choices[c.id]),at=order.indexOf(Core.node(state,chapters)),lines=order.slice(0,at+1).map(step=>{if(step==='choice')return {speaker:state.name||'你',text:c.question};return Core.line({...state,steps:{...state.steps,[c.id]:step}},chapters)});showDialog(`<h2>${c.title} · 对话回看</h2><div class="transcript">${lines.filter(x=>x.text).map(x=>`<p><strong>${esc(x.speaker)}</strong>${esc(x.text)}</p>`).join('')}</div>`)}
 function exportMemories(){let lines=['与本雅明同行 · 玩家回忆','玩家：'+(state.name||'同行者'),'所有剧情与语录式台词均为原创或依据观点改写，非原著逐字引文。',''];chapters.filter(c=>state.quotes.includes(c.id)).forEach(c=>{lines.push(c.title+' · '+c.place,c.aphorism,'事件背景：'+c.event,'说明：'+(c.reflection?.[1]?.text||''),'观点依据：卷轴 '+c.reference);if(state.choices[c.id]!==undefined)lines.push('你的回应：'+c.options[state.choices[c.id]][0],'同行回忆：'+c.options[state.choices[c.id]][2]);lines.push('')});let url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='与本雅明同行-语录与回忆.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 app.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b||b.disabled)return;let action=b.dataset.action;if(action==='begin-scene'){if(Core.begin(state,chapters))render()}else if(action==='context'){state.view='briefing';render()}else if(action==='map'){if(state.view==='scene'||state.view==='briefing')mapScroll=null;state.view='map';preview=Math.min(state.selected,Core.unlocked(state,chapters));render()}else if(action==='select'){preview=+b.dataset.index;render();document.querySelector?.('[data-action=select][data-index="'+preview+'"]')?.focus({preventScroll:true})}else if(action==='enter'||action==='replay'){let i=+b.dataset.index;if(Core.enter(state,chapters,i,action==='replay'||state.completed.includes(chapters[i].id)))render()}else if(action==='choose'){if(Core.choose(state,chapters,+b.dataset.option))render()}else if(action==='next')advance();else if(action==='next-map'){mapScroll=null;state.selected=Math.min(state.selected+1,chapters.length-1);preview=state.selected;state.view='map';render()}else if(action==='album'){state.view='album';render()}else if(action==='ending'){state.view='ending';render()}else if(action==='settings')settings();else if(action==='log')log();else if(action==='export')exportMemories()});
 dialog.addEventListener('click',e=>{let b=e.target.closest('[data-dialog-action]');if(!b)return;let a=b.dataset.dialogAction;if(a==='close')closeDialog();else if(a==='save-settings'){state.name=document.getElementById('player-name').value.trim().slice(0,24);state.mutedMotion=document.getElementById('reduce-animation').checked;closeDialog();render()}else if(a==='export')exportMemories();else if(a==='confirm-reset'){document.getElementById('dialog-content').innerHTML='<h2>重新从图书馆出发？</h2><p>本次同行的进度与回忆会被清除。导览网站的阅读记录不受影响。</p><button class="vn-primary" data-dialog-action="reset">重新开始</button><button data-dialog-action="close">保留当前旅程</button>'}else if(a==='reset'){state=Core.fresh();preview=0;closeDialog();render()}});
 document.addEventListener('keydown',e=>{if(dialog.open)return;if(e.key==='Escape'&&(state.view==='scene'||state.view==='briefing')){state.view='map';preview=state.selected;render();return}if(state.view==='scene'&&(e.code==='Space'||e.key==='Enter')&&!e.target.closest('button,a,input,select,textarea')){e.preventDefault();advance()}});
 save();render();
})();
